-- Scheduling foundation, part 1 of 3 — rooms and zones come from the blueprint.
-- Owner, 12 Sep 2026: "use room from facility page ... users can build details to each room,
-- modify staffing, departments, zones, rooms ... all on back end in settings".
--
-- What this does, all reversible, 0 data rows destroyed:
--   1. facility_room — the 30 rooms of A1.1 exactly as facility.ts draws them (generated by
--      tools/checks/facility-rooms-from-blueprint.mjs, not typed), editable by sign-off roles.
--   2. zones becomes the ONE zone table: it gains the columns the orphan `zone` table had,
--      15 zones are seeded from the blueprint's department groups, the three tg_*_zone
--      functions and the two views that read `zone` are repointed, and `zone` (0 rows) is dropped.
--   3. schedule_assignments (0 rows, referenced by nothing) is dropped — the third definition
--      of "a scheduled shift"; employee_schedules is the one f_post_schedule writes.
--   4. employee_schedules gains zone_id; the free-text zone column stays for the views that read it.
--   5. Write policies: zones / schedule_drafts / schedule_draft_lines had SELECT-only policies, so
--      the Schedule Builder's "Save draft" could never have written a row for any signed-in role.

-- 1 ─ facility_room ────────────────────────────────────────────────────────────────────────────
create table if not exists public.facility_room (
  room_id         text primary key,
  name            text not null,
  blueprint_zone  text not null check (blueprint_zone in ('office','process','canopy','dry','flower','service')),
  wing            text not null check (wing in ('cultivation','manufacturing','packaging','facility')),
  blueprint_dept  text not null,
  blueprint_group text not null,
  metrc_location  text unique,
  also_metrc      text[] not null default '{}',
  jobs            text,
  size            text check (size in ('LARGE','SMALL')),
  plant_capacity  integer check (plant_capacity > 0),
  x numeric not null, y numeric not null, w numeric not null, h numeric not null, zh numeric not null,
  alias_note      text,
  staffable       boolean not null default true,
  sort            integer not null,
  source          text not null default 'A1.1 Floor Plan · 90% CD · 2WR 220.090, via app/web/src/facility/data/facility.ts as committed 10 Sep 2026 (#185)',
  created_at      timestamptz not null default now(),
  updated_by      uuid,
  updated_at      timestamptz,
  retired_at      timestamptz,
  retired_why     text
);
comment on table public.facility_room is
  'The rooms of the Phase I building as the facility map draws them. One row per room on A1.1; metrc_location is the Metrc name where the plan label agrees. Editable in Settings by scheduling sign-off roles; the facility page still reads facility.ts until the front end is repointed (tracker 17).';

