alter table public.facility_room enable row level security;
drop policy if exists facility_room_read on public.facility_room;
create policy facility_room_read on public.facility_room for select using (true);
drop policy if exists facility_room_write on public.facility_room;
create policy facility_room_write on public.facility_room for all
  using (public.f_can_decide_hr()) with check (public.f_can_decide_hr());

-- 2 ─ zones: one table ───────────────────────────────────────────────────────────────────────
alter table public.zones
  add column if not exists zone_key         text,
  add column if not exists rooms            text[] not null default '{}',
  add column if not exists capacity         integer,
  add column if not exists what_happens_here text,
  add column if not exists blueprint_group  text,
  add column if not exists source           text,
  add column if not exists created_by       uuid,
  add column if not exists updated_by       uuid,
  add column if not exists updated_at       timestamptz,
  add column if not exists retired_at       timestamptz,
  add column if not exists retired_why      text;
create unique index if not exists zones_zone_key_uidx on public.zones (zone_key) where zone_key is not null;
comment on column public.zones.rooms is 'facility_room.room_id values. A zone with no rooms is an area, a line or a bench.';

-- Every room named on a zone must be a room on the blueprint.
create or replace function public.f_zones_rooms_must_exist() returns trigger
language plpgsql set search_path to 'public' as $$
declare bad text;
begin
  select string_agg(r, ', ') into bad
  from unnest(coalesce(new.rooms, '{}')) r
  where not exists (select 1 from facility_room f where f.room_id = r);
  if bad is not null then
    raise exception 'Not a room on the blueprint: %. Zones name facility_room.room_id values.', bad;
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists zones_rooms_must_exist on public.zones;
create trigger zones_rooms_must_exist before insert or update on public.zones
  for each row execute function public.f_zones_rooms_must_exist();

