  ('dock_inventory',     'Dock, Inventory & Warehouse','Shipping/Support',      array['dock-inv','ship','wh1'],  null, 'Packed product on the shelf, the dock, outbound orders, Warehouse #1.', 'Manufacturing · Dock / hold', 140),
  ('qa_quarantine',      'QA & Quarantine',         'Quality & Testing',        array['qa','quar'],              null, 'QA room and quarantine hold.', 'Operations · Floor / Manufacturing · Dock / hold', 150)
) as v(zone_key, name, dept, rooms, cap, what, grp, sort)
join d on d.name = v.dept
where not exists (select 1 from public.zones z where z.zone_key = v.zone_key);

-- Views that read the orphan `zone` table now read `zones`.
create or replace view public.v_zone_board as
select z.zone_key, z.name, d.name as department, z.rooms, z.capacity, z.what_happens_here, z.active, z.sort_order as sort,
       cardinality(z.rooms) as room_count,
       (select round(sum(b.lb_held), 1) from public.v_room_board_complete b
         where b.metrc_room_name in (select f.metrc_location from public.facility_room f where f.room_id = any(z.rooms)
                                     union select unnest(f.also_metrc) from public.facility_room f where f.room_id = any(z.rooms))) as lb_in_zone,
       (select sum(b.plants_now) from public.v_room_board_complete b
         where b.metrc_room_name in (select f.metrc_location from public.facility_room f where f.room_id = any(z.rooms)
                                     union select unnest(f.also_metrc) from public.facility_room f where f.room_id = any(z.rooms))) as plants_in_zone,
       case when cardinality(z.rooms) = 0 then 'Not tied to a room — this zone is an area, a line or a bench.' end as why_no_rooms,
       z.id as zone_id, z.department_id
from public.zones z
left join public.departments d on d.id = z.department_id
where z.active
order by z.sort_order, z.name;

create or replace view public.v_zone_vocabulary_drift as
select s.zone as zone_named_on_a_schedule, count(*) as schedule_rows,
       'This zone is named on a schedule but is not in the zone registry. Either add it with tg_add_zone or correct the schedule — free-text zones are how "F1" and "Flower Room #1" became two names for one room.'::text as what_to_do
from public.employee_schedules s
where nullif(btrim(coalesce(s.zone, '')), '') is not null
  and not exists (select 1 from public.zones z where z.zone_key = s.zone or z.name = s.zone)
group by s.zone;

-- The three zone-registry functions now write `zones`.
create or replace function public.tg_add_zone(p_name text, p_department text default null, p_rooms text[] default '{}', p_capacity integer default null, p_what_happens_here text default null)
returns text language plpgsql set search_path to 'public' as $$
declare v_key text; bad text; v_dept uuid;
begin
  if not public.f_can_decide_hr() then
    raise exception 'Only a scheduling sign-off role may add a zone.' using errcode = '42501';
  end if;
  if p_name is null or btrim(p_name) = '' then
    raise exception 'A zone needs a name people would actually say out loud.';
  end if;
  v_key := btrim(left(regexp_replace(lower(btrim(p_name)), '[^a-z0-9]+', '_', 'g'), 40), '_-');
  if v_key !~ '^[a-z0-9_-]{2,40}$' then
    raise exception 'Could not make a usable key from "%". Try a name with letters in it.', p_name;
  end if;
  if exists (select 1 from zones where zone_key = v_key) then
    raise exception 'A zone called "%" already exists. Rename that one or choose another name.', p_name;
  end if;
  if p_department is not null then
    select id into v_dept from departments where name = btrim(p_department);
    if v_dept is null then raise exception 'Not a department: %. Departments are the 8 in Settings.', p_department; end if;
  end if;
  -- rooms may be given as room_id, blueprint name or Metrc name; they are stored as room_id.
  select string_agg(r, ', ') into bad from unnest(coalesce(p_rooms,'{}')) r
  where not exists (select 1 from facility_room f where f.room_id = r or f.name = r or f.metrc_location = r or r = any(f.also_metrc));
  if bad is not null then
    raise exception 'Not a room on the blueprint: %. Leave rooms empty if this zone is not a room.', bad;
  end if;
  insert into zones (zone_key, name, department_id, description, rooms, capacity, what_happens_here, active, sort_order, created_by, source)
  select v_key, btrim(p_name), v_dept, nullif(btrim(coalesce(p_what_happens_here,'')),''),
         coalesce((select array_agg(distinct f.room_id) from unnest(coalesce(p_rooms,'{}')) r
                   join facility_room f on f.room_id = r or f.name = r or f.metrc_location = r or r = any(f.also_metrc)), '{}'),
         p_capacity, nullif(btrim(coalesce(p_what_happens_here,'')),''), true,
         coalesce((select max(sort_order) from zones), 0) + 10, auth.uid(), 'tg_add_zone';
  return v_key;
end $$;

create or replace function public.tg_rename_zone(p_key text, p_name text)
returns void language plpgsql set search_path to 'public' as $$
begin
  if not public.f_can_decide_hr() then raise exception 'Only a scheduling sign-off role may rename a zone.' using errcode = '42501'; end if;
  if p_name is null or btrim(p_name) = '' then raise exception 'A zone needs a name.'; end if;
  update zones set name = btrim(p_name), updated_by = auth.uid() where zone_key = p_key;
  if not found then raise exception 'No zone with key %.', p_key; end if;
end $$;

create or replace function public.tg_retire_zone(p_key text, p_why text)
returns void language plpgsql set search_path to 'public' as $$
begin
  if not public.f_can_decide_hr() then raise exception 'Only a scheduling sign-off role may retire a zone.' using errcode = '42501'; end if;
  if p_why is null or btrim(p_why) = '' then raise exception 'Say why the zone is retired; the reason is kept.'; end if;
  update zones set active = false, retired_at = now(), retired_why = btrim(p_why), updated_by = auth.uid() where zone_key = p_key and active;
  if not found then raise exception 'No active zone with key %.', p_key; end if;
end $$;

-- The orphan. 0 rows, no remaining reader; definition stays in migration history.
drop table if exists public.zone;

-- 3 ─ the third "scheduled shift" table: 0 rows, referenced by no view, function or page.
drop table if exists public.schedule_assignments;

-- 4 ─ employee_schedules gains the real zone reference; the text column stays for existing readers.
alter table public.employee_schedules add column if not exists zone_id uuid references public.zones(id);
create index if not exists employee_schedules_zone_id_idx on public.employee_schedules (zone_id, work_date);

-- 5 ─ write policies that were missing (the builder page inserts drafts and lines directly).
drop policy if exists zones_write on public.zones;
create policy zones_write on public.zones for all using (public.f_can_decide_hr()) with check (public.f_can_decide_hr());
drop policy if exists schedule_drafts_write on public.schedule_drafts;
create policy schedule_drafts_write on public.schedule_drafts for all using (public.f_can_decide_hr()) with check (public.f_can_decide_hr());
drop policy if exists schedule_draft_lines_write on public.schedule_draft_lines;
create policy schedule_draft_lines_write on public.schedule_draft_lines for all using (public.f_can_decide_hr()) with check (public.f_can_decide_hr());
